ctx.lineTo(basketX + 35, groundY - 10);
ctx.moveTo(basketX + 25, groundY - basketH + 10);
ctx.lineTo(basketX + 30, groundY - basketH);
ctx.lineTo(basketX + 35, groundY - basketH + 10);
