function ai_appearContainer1111(container, cb) {
    const dpr = window.devicePixelRatio || 1;
    const logicalWidth = 640; 
    const padding = 40;       
    const fontSize = 30; 
    const unit = 150;      

    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    function updateBounds(x, y, r = 0) {
      minX = Math.min(minX, x - r);
      maxX = Math.max(maxX, x + r);
      minY = Math.min(minY, y - r);
      maxY = Math.max(maxY, y + r);
    }
    function updateTextBounds(text, x, y, align = 'center') {
        const estCharWidth = fontSize * 0.6; 
        const width = text.length * estCharWidth;
        if (align === 'left') updateBounds(x + width, y, 0);
        else if (align === 'right') updateBounds(x - width, y, 0); 
        else { updateBounds(x - width/2, y, 0); updateBounds(x + width/2, y, 0); }
        updateBounds(x, y - fontSize, 0); 
        updateBounds(x, y + fontSize/3, 0); 
    }

    updateBounds(0.5 * unit, 0, 0);
    updateBounds(4 * unit, 0, 0);
    const hx = 1 * unit;
    updateBounds(hx, -1.6 * unit, 0.1 * unit);
    updateBounds(hx - 0.2 * unit, 0, 0);
    updateBounds(hx + 0.2 * unit, 0, 0);
    const dx = hx - 0.4 * unit;
    updateTextBounds('身高约1.6m', dx, -1.65 * unit, 'center');
    const stickX = 2.5 * unit;
    updateBounds(stickX, -1.5 * unit, 4);
    updateBounds(stickX, 0, 4);
    updateTextBounds('捣棒约1.5m', stickX, -1.55 * unit, 'center');

    if (minX === Infinity) { minX = 0; maxX = 640; minY = 0; maxY = 300; }
    const contentW = maxX - minX;
    const contentH = maxY - minY;
    const maxSafeW = logicalWidth - padding * 2;
    let safeScale = 1;
    if (contentW > maxSafeW) { safeScale = maxSafeW / contentW; }
    const finalHeight = (contentH * safeScale) + padding * 2;

    const cvs = document.createElement('canvas');
    cvs.style.width = '100%';  
    cvs.style.height = 'auto'; 
    cvs.width = logicalWidth * dpr;
    cvs.height = finalHeight * dpr;
    container.appendChild(cvs);

    const ctx = cvs.getContext('2d');
    ctx.scale(dpr, dpr);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.font = `italic ${fontSize}px "Times New Roman"`; 
    ctx.textBaseline = 'middle';

    const offsetX = (logicalWidth - contentW * safeScale) / 2 - minX * safeScale;
    const offsetY = padding - minY * safeScale;
    ctx.translate(offsetX, offsetY);
    ctx.scale(safeScale, safeScale); 

    ctx.beginPath();
    ctx.moveTo(0.5 * unit, 0);
    ctx.lineTo(4 * unit, 0);
    ctx.lineWidth = 4;
    ctx.strokeStyle = '#A4B0BE'; 
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(hx, -1.5 * unit, 0.1 * unit, 0, Math.PI*2);
    ctx.fillStyle = '#A4B0BE';
    ctx.fill();
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(hx, -1.4 * unit); 
    ctx.lineTo(hx, -0.8 * unit); 
    ctx.moveTo(hx, -1.3 * unit);
    ctx.lineTo(hx - 0.2 * unit, -0.9 * unit); 
    ctx.moveTo(hx, -1.3 * unit);
    ctx.lineTo(hx + 0.2 * unit, -0.9 * unit); 
    ctx.moveTo(hx, -0.8 * unit);
    ctx.lineTo(hx - 0.2 * unit, 0); 
    ctx.moveTo(hx, -0.8 * unit);
    ctx.lineTo(hx + 0.2 * unit, 0); 
    ctx.lineWidth = 4;
    ctx.strokeStyle = '#333333';
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(dx, 0);
    ctx.lineTo(dx, -1.6 * unit);
    ctx.lineWidth = 2;
    ctx.setLineDash([5, 5]);
    ctx.strokeStyle = '#A4B0BE';
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#333333';
    ctx.textAlign = 'center';
    ctx.fillText('身高约1.6m', dx, -1.65 * unit);

    ctx.beginPath();
    ctx.moveTo(stickX, 0);
    ctx.lineTo(stickX, -1.5 * unit);
    ctx.lineWidth = 8;
    ctx.strokeStyle = '#FF6B6B'; 
    ctx.stroke();

    ctx.fillStyle = '#FF6B6B';
    ctx.fillText('捣棒约1.5m', stickX, -1.55 * unit);

    if (typeof cb === 'function') cb();
}

