function ai_drawChopsticks1111(container, cb) {
    const dpr = window.devicePixelRatio || 1;
    const logicalWidth = 640; 
    const padding = 40;       

    const fontSize = 30; 
    const unit = 15;      

    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    function updateBounds(x, y, r = 0) {
      minX = Math.min(minX, x - r);
      maxX = Math.max(maxX, x + r);
      minY = Math.min(minY, y - r);
      maxY = Math.max(maxY, y + r);
    }
    function updateTextBounds(text, x, y, align = 'center') {
        const estCharWidth = fontSize * 0.6; 
        const width = text.length * estCharWidth;
        if (align === 'left') updateBounds(x + width, y, 0);
        else if (align === 'right') updateBounds(x - width, y, 0); 
        else { updateBounds(x - width/2, y, 0); updateBounds(x + width/2, y, 0); }
        updateBounds(x, y - fontSize, 0); 
        updateBounds(x, y + fontSize/3, 0); 
    }

    // 尺子边界
    updateBounds(-2 * unit, 50, 0);
    updateBounds(32 * unit, 110, 0);

    // 筷子边界
    updateBounds(0, 10, 10);
    updateBounds(25 * unit, 30, 10);

    // 文本边界估算
    updateTextBounds('25cm', 25 * unit, -20, 'center');
    updateTextBounds('0', 0, 80, 'center');
    updateTextBounds('30', 30 * unit, 80, 'center');

    if (minX === Infinity) { minX = 0; maxX = 640; minY = 0; maxY = 300; }
    const contentW = maxX - minX;
    const contentH = maxY - minY;

    const maxSafeW = logicalWidth - padding * 2;
    let safeScale = 1;
    if (contentW > maxSafeW) { safeScale = maxSafeW / contentW; }

    const finalHeight = (contentH * safeScale) + padding * 2;

    const cvs = document.createElement('canvas');
    cvs.style.width = '100%';  
    cvs.style.height = 'auto'; 
    cvs.width = logicalWidth * dpr;
    cvs.height = finalHeight * dpr;
    container.appendChild(cvs);

    const ctx = cvs.getContext('2d');
    ctx.scale(dpr, dpr);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.font = `italic ${fontSize}px "Times New Roman"`; 

    const offsetX = (logicalWidth - contentW * safeScale) / 2 - minX * safeScale;
    const offsetY = padding - minY * safeScale;

    ctx.translate(offsetX, offsetY);
    ctx.scale(safeScale, safeScale); 

    // 1. 绘制尺子主体轮廓
    ctx.fillStyle = 'rgba(164, 176, 190, 0.2)'; 
    ctx.fillRect(-2 * unit, 50, 34 * unit, 60);
    ctx.strokeStyle = '#333333';
    ctx.lineWidth = 4;
    ctx.strokeRect(-2 * unit, 50, 34 * unit, 60);

    // 2. 绘制尺子刻度与文字
    ctx.fillStyle = '#333333';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    for (let i = 0; i <= 30; i++) {
        let x = i * unit;
        let h = 10;
        if (i % 5 === 0) h = 18;
        if (i % 10 === 0) {
            h = 25;
            ctx.fillText(i.toString(), x, 50 + h + 5);
        }
        ctx.beginPath();
        ctx.moveTo(x, 50);
        ctx.lineTo(x, 50 + h);
        ctx.stroke();
    }

    // 3. 绘制上方筷子示意
    ctx.fillStyle = '#FF9F43'; // 暖橙色模拟木质感
    ctx.beginPath();
    ctx.moveTo(0, 15); 
    ctx.lineTo(25 * unit, 10); 
    ctx.lineTo(25 * unit + 5, 20); 
    ctx.lineTo(25 * unit, 30);
    ctx.lineTo(0, 25);
    ctx.arc(0, 20, 5, Math.PI/2, Math.PI*1.5, false);
    ctx.fill();
    ctx.strokeStyle = '#333333';
    ctx.lineWidth = 4;
    ctx.stroke();

    // 筷子后端纹理装饰
    ctx.fillStyle = '#333333';
    ctx.beginPath();
    ctx.fillRect(20 * unit, 12, 1 * unit, 16);
    ctx.fillRect(22 * unit, 11, 1 * unit, 18);

    // 4. 长度虚线标注
    ctx.strokeStyle = '#48DBFB'; // 辅助强调色
    ctx.lineWidth = 4;
    ctx.setLineDash([10, 10]);
    ctx.beginPath();
    ctx.moveTo(25 * unit, 30);
    ctx.lineTo(25 * unit, 50);
    ctx.stroke();
    ctx.setLineDash([]);

    // 标注 25cm
    ctx.fillStyle = '#FF6B6B'; // 重点强调色
    ctx.font = `italic ${fontSize}px "Times New Roman"`; 
    ctx.textBaseline = 'bottom';
    ctx.fillText('25cm', 25 * unit, -10);

    if (typeof cb === 'function') cb();
}

