function ai_drawMacroAnimation(container, cb){
const dpr = window.devicePixelRatio || 1;
const logicalWidth = 640;
const contentH = 320;
const wrapper = document.createElement('div');
wrapper.style.display = 'flex';
wrapper.style.flexDirection = 'column';
wrapper.style.alignItems = 'center';
wrapper.style.width = '100%';
container.appendChild(wrapper);
const cvs = document.createElement('canvas');
cvs.style.width = '100%';
cvs.style.height = 'auto';
cvs.width = logicalWidth * dpr;
cvs.height = contentH * dpr;
wrapper.appendChild(cvs);
const ctx = cvs.getContext('2d');
ctx.scale(dpr, dpr);
ctx.lineCap = 'round';
ctx.lineJoin = 'round';
let progress = 0;
let isAnimating = false;
let reqId = null;
const btn = document.createElement('button');
btn.textContent = "播放运动过程";
btn.style.marginTop = '15px';
btn.style.padding = '8px 16px';
btn.style.backgroundColor = '#48DBFB';
btn.style.color = '#FFFFFF';
btn.style.border = 'none';
btn.style.borderRadius = '20px';
btn.style.fontSize = '16px';
btn.style.fontWeight = 'bold';
btn.style.boxShadow = '0 4px 0 #0abde3';
btn.style.cursor = 'pointer';
wrapper.appendChild(btn);
function drawScene(prog){
ctx.clearRect(0, 0, logicalWidth, contentH);
ctx.fillStyle = '#2C3E50';
ctx.fillRect(0, 0, logicalWidth, contentH);
ctx.beginPath();
ctx.arc(320, 0, 80, 0, Math.PI * 2);
ctx.fillStyle = '#FF9F43';
ctx.fill();
ctx.fillStyle = '#FFFFFF';
ctx.font = 'normal 24px "Times New Roman"';
ctx.textAlign = 'center';
ctx.fillText("太阳", 320, 45);
ctx.beginPath();
ctx.arc(120, 240, 60, 0, Math.PI * 2);
ctx.fillStyle = '#48DBFB';
ctx.fill();
ctx.fillStyle = '#FFFFFF';
ctx.fillText("地球 (参照物)", 120, 250);
ctx.beginPath();
ctx.arc(520, 240, 45, 0, Math.PI * 2);
ctx.fillStyle = '#FF6B6B';
ctx.fill();
ctx.fillStyle = '#FFFFFF';
ctx.fillText("火星", 520, 250);
const startX = 180;
const startY = 160;
const endX = 460;
const endY = 160;
const curX = startX + (endX - startX) * prog;
const curY = startY + (endY - startY) * prog;
ctx.beginPath();
ctx.moveTo(startX, startY);
ctx.lineTo(endX, endY);
ctx.strokeStyle = 'rgba(255,255,255,0.3)';
ctx.lineWidth = 2;
ctx.setLineDash([8, 8]);
ctx.stroke();
ctx.setLineDash([]);
ctx.beginPath();
ctx.moveTo(120, 240);
ctx.lineTo(curX, curY);
ctx.strokeStyle = '#1DD1A1';
ctx.lineWidth = 3;
ctx.stroke();
const midX = (120 + curX) / 2;
const midY = (240 + curY) / 2;
ctx.fillStyle = '#1DD1A1';
ctx.fillText("距离在变大", midX - 30, midY - 10);
ctx.fillStyle = '#E0E0E0';
ctx.beginPath();
ctx.moveTo(curX + 20, curY);
ctx.lineTo(curX - 20, curY - 15);
ctx.lineTo(curX - 20, curY + 15);
ctx.fill();
ctx.fillStyle = '#FF6B6B';
ctx.fillText("飞船 (研究对象)", curX, curY - 25);
}
function animate(){
progress += 0.01;
if(progress > 1) progress = 1;
drawScene(progress);
if(progress < 1){
reqId = requestAnimationFrame(animate);
}else{
isAnimating = false;
btn.textContent = "重播运动过程";
}
}
btn.onclick = () => {
if(isAnimating) return;
isAnimating = true;
progress = 0;
if(reqId) cancelAnimationFrame(reqId);
animate();
};
drawScene(0);
if(cb) cb();
}

