    ctx.stroke();
    ctx.setLineDash([]);

    const shipX = cx + 220 * Math.cos(-Math.PI/4);
    const shipY = cy + 120 + 80 * Math.sin(-Math.PI/4);

    ctx.fillStyle = '#FF9F43';
    ctx.fillRect(shipX - 20, shipY - 10, 40, 20);
    ctx.fillStyle = '#1DD1A1';
    ctx.fillRect(shipX - 50, shipY - 5, 25, 10);
    ctx.fillRect(shipX + 25, shipY - 5, 25, 10);

    ctx.strokeStyle = '#FF6B6B';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(shipX + 30, shipY - 20);
    ctx.lineTo(shipX + 70, shipY - 40);
    ctx.lineTo(shipX + 60, shipY - 45);
    ctx.moveTo(shipX + 70, shipY - 40);
    ctx.lineTo(shipX + 70, shipY - 30);
    ctx.stroke();

