    if (contentW > maxSafeW) { safeScale = maxSafeW / contentW; }
    const finalHeight = (contentH * safeScale) + padding * 2;

    const cvs = document.createElement('canvas');
    cvs.style.width = '100%';
    cvs.style.height = 'auto';
    cvs.width = logicalWidth * dpr;
    cvs.height = finalHeight * dpr;
    wrapper.appendChild(cvs);

    const btn = document.createElement('div');
    btn.innerText = '播放-对接过程';
    btn.style.marginTop = '15px';
    btn.style.padding = '12px 24px';
    btn.style.backgroundColor = '#48DBFB';
    btn.style.color = '#FFFFFF';
    btn.style.fontSize = '16px';
    btn.style.fontWeight = 'bold';
    btn.style.borderRadius = '20px';
    btn.style.boxShadow = '0 4px 0 #0abde3';
    btn.style.cursor = 'pointer';
    btn.style.userSelect = 'none';
    btn.style.transition = 'transform 0.1s, box-shadow 0.1s';
    wrapper.appendChild(btn);
    container.appendChild(wrapper);

    const ctx = cvs.getContext('2d');
    ctx.scale(dpr, dpr);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.font = `italic ${fontSize}px "Times New Roman"`;

    const offsetX = (logicalWidth - contentW * safeScale) / 2 - minX * safeScale;
    const offsetY = padding - minY * safeScale;

    let isAnimating = false;
    let startX = 80;
    let targetX = 360;
    let currentX = startX;
    const ssCenter = {x: 500, y: 220};

    function draw() {
        ctx.save();
        ctx.clearRect(0, 0, logicalWidth, finalHeight);
        ctx.translate(offsetX, offsetY);
        ctx.scale(safeScale, safeScale);

        ctx.lineWidth = 4;
        ctx.strokeStyle = '#2C3E50';

        ctx.fillStyle = '#1DD1A1';
        ctx.fillRect(ssCenter.x, ssCenter.y - 70, 30, 140);
        ctx.strokeRect(ssCenter.x, ssCenter.y - 70, 30, 140);

        ctx.fillStyle = '#FF9F43';
        ctx.fillRect(ssCenter.x - 50, ssCenter.y - 35, 70, 70);
        ctx.strokeRect(ssCenter.x - 50, ssCenter.y - 35, 70, 70);

        ctx.fillStyle = '#A4B0BE';
        ctx.fillRect(ssCenter.x - 70, ssCenter.y - 15, 20, 30);
        ctx.strokeRect(ssCenter.x - 70, ssCenter.y - 15, 20, 30);

        ctx.fillStyle = '#2C3E50';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText("空间站", ssCenter.x - 15, ssCenter.y + 60);

        const shipY = ssCenter.y;
        ctx.fillStyle = '#48DBFB';
        ctx.beginPath();
        ctx.moveTo(currentX, shipY - 15);
        ctx.lineTo(currentX + 40, shipY - 15);
        ctx.lineTo(currentX + 50, shipY);
        ctx.lineTo(currentX + 40, shipY + 15);
        ctx.lineTo(currentX, shipY + 15);
        ctx.closePath();
        ctx.fill(); ctx.stroke();

        ctx.fillStyle = '#A4B0BE';
        ctx.fillRect(currentX - 20, shipY - 10, 20, 20);
        ctx.strokeRect(currentX - 20, shipY - 10, 20, 20);

        ctx.fillStyle = '#2C3E50';
        ctx.fillText("飞船", currentX + 15, shipY + 50);

        const p1 = currentX + 50;
        const p2 = ssCenter.x - 70;
        const dist = p2 - p1;

        if (dist > 5) {
            ctx.strokeStyle = '#FF6B6B';
            ctx.setLineDash([8, 8]);
            ctx.beginPath();
            ctx.moveTo(p1 + 5, shipY);
            ctx.lineTo(p2 - 5, shipY);
            ctx.stroke();
            ctx.setLineDash([]);

            ctx.beginPath();
            ctx.moveTo(p1 + 15, shipY - 10);
            ctx.lineTo(p1 + 5, shipY);
            ctx.lineTo(p1 + 15, shipY + 10);
            ctx.stroke();
            ctx.beginPath();
            ctx.moveTo(p2 - 15, shipY - 10);
            ctx.lineTo(p2 - 5, shipY);
            ctx.lineTo(p2 - 15, shipY + 10);
            ctx.stroke();

            ctx.fillStyle = '#FF6B6B';
            ctx.fillText(`相对距离缩小中...`, (p1 + p2)/2, shipY - 20);

            ctx.fillStyle = '#2C3E50';
            ctx.fillText("对接过程：飞船逐渐靠近空间站", 320, 80);
            ctx.fillStyle = '#FF6B6B';
            ctx.fillText("（位置改变，互相为运动状态）", 320, 120);
        } else {
            ctx.fillStyle = '#1DD1A1';
            ctx.fillText("对接完成！", 320, 80);
            ctx.fillText("（此时互相为静止状态）", 320, 120);
        }
        ctx.restore();
    }

    function animate() {
        if(currentX < targetX) {
            currentX += 3;
            draw();
            requestAnimationFrame(animate);
        } else {
            isAnimating = false;
            btn.innerText = '重播-对接过程';
        }
    }

    draw();

    btn.onclick = () => {
        if(isAnimating) return;
        btn.style.transform = 'translateY(2px)';
        btn.style.boxShadow = '0 2px 0 #0abde3';
        setTimeout(() => {
            btn.style.transform = 'none';
            btn.style.boxShadow = '0 4px 0 #0abde3';
        }, 100);

        isAnimating = true;
        currentX = startX;
        btn.innerText = '对接中...';
        animate();
    };

    if(typeof cb === 'function') cb();
}

