    cvs.height = finalHeight * dpr;
    wrapper.appendChild(cvs);

    const btn = document.createElement('button');
    btn.innerText = '演示发射过程';
    btn.style.marginTop = '15px';
    btn.style.padding = '12px 24px';
    btn.style.backgroundColor = '#FF9F43';
    btn.style.color = '#FFFFFF';
    btn.style.fontSize = '16px';
    btn.style.fontWeight = 'bold';
    btn.style.border = 'none';
    btn.style.borderRadius = '20px';
    btn.style.boxShadow = '0 4px 0 #D35400';
    btn.style.cursor = 'pointer';
    wrapper.appendChild(btn);

    container.appendChild(wrapper);

    const ctx = cvs.getContext('2d');
    ctx.scale(dpr, dpr);
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    const offsetX = (logicalWidth - contentW * safeScale) / 2 - minX * safeScale;
    const offsetY = padding - minY * safeScale;

    let isAnimating = false;
    let progress = 0;
    let rocketY = 340;

    function drawScene() {
        ctx.clearRect(0, 0, logicalWidth, finalHeight);
        ctx.save();
        ctx.translate(offsetX, offsetY);
        ctx.scale(safeScale, safeScale);

        ctx.beginPath();
        ctx.moveTo(80, 400);
        ctx.lineTo(560, 400);
        ctx.lineWidth = 6;
        ctx.strokeStyle = '#2C3E50';
        ctx.stroke();

        ctx.fillStyle = '#2C3E50';
        ctx.font = `italic 24px "Times New Roman"`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText("地 面", 320, 410);

        const cx = 320;
        const cy = rocketY;
        const w = 50;
        const h = 120;

        if (progress > 0 && progress < 1) {
            ctx.beginPath();
            ctx.moveTo(cx - 18, cy + h/2);
            ctx.lineTo(cx, cy + h/2 + 35 + Math.random()*25);
            ctx.lineTo(cx + 18, cy + h/2);
            ctx.fillStyle = '#FF6B6B';
            ctx.fill();
        }

        ctx.beginPath();
        ctx.rect(cx - w/2, cy - h/2, w, h);
        ctx.fillStyle = '#A4B0BE';
        ctx.fill();
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#2C3E50';
        ctx.stroke();

        ctx.beginPath();
        ctx.moveTo(cx - w/2, cy - h/2);
        ctx.lineTo(cx, cy - h/2 - 45);
        ctx.lineTo(cx + w/2, cy - h/2);
        ctx.closePath();
        ctx.fillStyle = '#FF9F43';
        ctx.fill();
        ctx.stroke();

        const satY = cy - 25;
        ctx.beginPath();
        ctx.arc(cx, satY, 14, 0, Math.PI * 2);
        ctx.fillStyle = '#48DBFB';
        ctx.fill();
        ctx.stroke();

        ctx.fillStyle = '#2C3E50';
        ctx.font = `italic 22px "Times New Roman"`;
        ctx.textBaseline = 'middle';
        ctx.fillText("火箭", cx, cy + 20);

        ctx.fillStyle = '#2C3E50';
        ctx.font = `italic 14px "Times New Roman"`;
        ctx.fillText("H星", cx, satY);

        ctx.restore();
    }

    drawScene();

    btn.onclick = () => {
        if (isAnimating) return;
        isAnimating = true;
        progress = 0;
        rocketY = 340;

        btn.style.transform = 'translateY(4px)';
        btn.style.boxShadow = '0 0 0 #D35400';
        setTimeout(() => {
            btn.style.transform = 'translateY(0)';
            btn.style.boxShadow = '0 4px 0 #D35400';
        }, 100);

        let startTime = null;
        function animate(time) {
            if (!startTime) startTime = time;
            progress = (time - startTime) / 2500;
            if (progress > 1) progress = 1;

            rocketY = 340 - 240 * Math.pow(progress, 1.5);

            drawScene();

            if (progress < 1) {
                requestAnimationFrame(animate);
            } else {
                isAnimating = false;
                btn.innerText = '重播 - 发射过程';
            }
        }
        requestAnimationFrame(animate);
    };

    if (typeof cb === 'function') cb();
}

