function ai_playMotion1111(container, cb) {
    const dpr = window.devicePixelRatio || 1;
    const logicalWidth = 640; 
    const padding = 40;       

    const fontSize = 30; 
    const unit = 1;      

    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    function updateBounds(x, y, r = 0) {
      minX = Math.min(minX, x - r);
      maxX = Math.max(maxX, x + r);
      minY = Math.min(minY, y - r);
      maxY = Math.max(maxY, y + r);
    }

    function updateTextBounds(text, x, y, align = 'center') {
        const estCharWidth = fontSize * 0.6; 
        const width = text.length * estCharWidth;
        if (align === 'left') updateBounds(x + width, y, 0);
        else if (align === 'right') updateBounds(x - width, y, 0); 
        else { updateBounds(x - width/2, y, 0); updateBounds(x + width/2, y, 0); }
        updateBounds(x, y - fontSize, 0); 
        updateBounds(x, y + fontSize/3, 0); 
    }

    function toScreen(x, y) {
        return { x: x, y: y };
    }

    /**
     * 绘制几何角度标记（自动处理劣弧）
    * @param ctx Canvas上下文
    * @param pC 顶点坐标 {x, y} (数学坐标)
    * @param p1 边1上的点坐标 {x, y} (数学坐标) - 用于确定起始边
    * @param p2 边2上的点坐标 {x, y} (数学坐标) - 用于确定终止边
    * @param r 屏幕像素半径 (建议取 canvas.width * 0.05)
    */
    function drawAngleMark(ctx, pC, p1, p2, r) {
        var sC = toScreen(pC.x, pC.y);
        var s1 = toScreen(p1.x, p1.y);
        var s2 = toScreen(p2.x, p2.y);
        var a1 = Math.atan2(s1.y - sC.y, s1.x - sC.x);
        var a2 = Math.atan2(s2.y - sC.y, s2.x - sC.x);
        var diff = a2 - a1;
        while (diff <= -Math.PI) diff += 2 * Math.PI;
        while (diff > Math.PI) diff -= 2 * Math.PI;
        ctx.beginPath();
        ctx.arc(sC.x, sC.y, r, a1, a1 + diff, diff < 0);
        ctx.stroke();
    }

    const treeX = 150;
    const treeY = 150;

    updateBounds(treeX, treeY, 60); 
    updateBounds(treeX, treeY + 80, 20); 
    updateTextBounds("景物", treeX, treeY + 130);

    updateBounds(50, 230, 0);
    updateBounds(590, 230, 0); 

    let horseStartX = 150;
    let horseTargetX = 480;
    let horseY = 190;
    updateBounds(horseTargetX, horseY, 40);
    updateTextBounds("诗人", horseTargetX, horseY + 50);

    if (minX === Infinity) { minX = 0; maxX = 640; minY = 0; maxY = 300; }
    const contentW = maxX - minX;
    const contentH = maxY - minY;

    const maxSafeW = logicalWidth - padding * 2;
    let safeScale = 1;
    if (contentW > maxSafeW) { safeScale = maxSafeW / contentW; }

    const finalHeight = (contentH * safeScale) + padding * 2;

    const wrapper = document.createElement('div');
    wrapper.style.display = 'flex';
    wrapper.style.flexDirection = 'column';
    wrapper.style.alignItems = 'center';
    wrapper.style.width = '100%';

    const cvs = document.createElement('canvas');
    cvs.style.width = '100%';  
    cvs.style.height = 'auto'; 
    cvs.width = logicalWidth * dpr;
    cvs.height = finalHeight * dpr;
    wrapper.appendChild(cvs);

    const btn = document.createElement('div');
    btn.innerText = '播放运动过程';
    btn.style.marginTop = '15px';
    btn.style.padding = '10px 30px';
    btn.style.backgroundColor = '#FF9F43';
    btn.style.color = '#FFFFFF';
    btn.style.fontSize = '14px';
    btn.style.fontWeight = 'bold';
    btn.style.borderRadius = '20px';
    btn.style.boxShadow = '0 4px 0 #D35400';
    btn.style.cursor = 'pointer';
    btn.style.userSelect = 'none';
    wrapper.appendChild(btn);

    container.appendChild(wrapper);

    const ctx = cvs.getContext('2d');

    const offsetX = (logicalWidth - contentW * safeScale) / 2 - minX * safeScale;
    const offsetY = padding - minY * safeScale;

    let isAnimating = false;
    let progress = 0; 

    function drawScene() {
        ctx.clearRect(0, 0, cvs.width, cvs.height);
        ctx.save();
        ctx.scale(dpr, dpr);
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        ctx.translate(offsetX, offsetY);
        ctx.scale(safeScale, safeScale); 

        ctx.beginPath();
        ctx.moveTo(minX, 230);
        ctx.lineTo(maxX, 230);
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#A4B0BE';
        ctx.stroke();

        ctx.fillStyle = '#A4B0BE'; 
        ctx.fillRect(treeX - 10, treeY, 20, 80);
        ctx.beginPath();
        ctx.arc(treeX, treeY, 40, 0, Math.PI * 2);
        ctx.fillStyle = '#1DD1A1'; 
        ctx.fill();

        ctx.font = `italic ${fontSize}px "Times New Roman"`; 
        ctx.fillStyle = '#333333';
        ctx.textAlign = 'center';
        ctx.fillText('景物', treeX, treeY + 120);

        let currentX = horseStartX + (horseTargetX - horseStartX) * progress;

        if (progress > 0) {
            ctx.beginPath();
            ctx.moveTo(horseStartX, horseY);
            ctx.lineTo(currentX, horseY);
            ctx.lineWidth = 4;
            ctx.strokeStyle = '#FF9F43';
            ctx.setLineDash([10, 10]);
            ctx.stroke();
            ctx.setLineDash([]);
        }

        ctx.beginPath();
        ctx.arc(currentX, horseY, 25, 0, Math.PI * 2);
        ctx.fillStyle = '#FF6B6B';
        ctx.fill();
        ctx.lineWidth = 4;
        ctx.strokeStyle = '#333333';
        ctx.stroke();

        ctx.font = `italic ${fontSize}px "Times New Roman"`; 
        ctx.fillStyle = '#333333';
        ctx.textAlign = 'center';
        ctx.fillText('诗人', currentX, horseY + 60);

        if (progress > 0.1) {
            ctx.beginPath();
            const distStart = treeX + 50;
            const distEnd = currentX - 35;
            if (distEnd > distStart) {
                ctx.moveTo(distStart, 160);
                ctx.lineTo(distEnd, 160);
                ctx.lineWidth = 2;
                ctx.strokeStyle = '#48DBFB';
                ctx.stroke();

                ctx.fillStyle = '#48DBFB';
                ctx.font = `italic 20px "Times New Roman"`; 
                ctx.fillText('相对位置改变', (distStart + distEnd)/2, 150);
            }
        }

        ctx.restore();
    }

    drawScene();

    btn.onclick = () => {
        if (isAnimating) return;
        isAnimating = true;
        progress = 0;

        const duration = 1500;
        const startTime = performance.now();

        function animate(time) {
            let p = (time - startTime) / duration;
            if (p >= 1) {
                p = 1;
                progress = p;
                drawScene();
                isAnimating = false;
                btn.innerText = '重播-运动过程';
                return;
            }
            progress = 1 - Math.pow(1 - p, 3);
            drawScene();
            requestAnimationFrame(animate);
        }
        requestAnimationFrame(animate);
    }

    if (typeof cb === 'function') cb();
}

