ctx.moveTo(midX + arrowLen * Math.cos(angle), midY + arrowLen * Math.sin(angle));
ctx.lineTo(midX - arrowLen * Math.cos(angle - Math.PI/6), midY - arrowLen * Math.sin(angle - Math.PI/6));
ctx.lineTo(midX - arrowLen * Math.cos(angle + Math.PI/6), midY - arrowLen * Math.sin(angle + Math.PI/6));
ctx.closePath();
ctx.fillStyle = color;
ctx.fill();
}
const S = {x: 80, y: 50};
