let oldP = getPoints(startH);
drawLineWithArrow(ctx, oldP.P.x, oldP.P.y, oldP.Pref.x, oldP.Pref.y, '#A4B0BE', true);
drawLineWithArrow(ctx, oldP.P.x, oldP.P.y, oldP.Prefrac.x, oldP.Prefrac.y, '#A4B0BE', true);
