ctx.textAlign = 'center';
ctx.textBaseline = 'middle';
let mx_i = (S.x-P.x)/Math.hypot(S.x-P.x, S.y-P.y) + (N_up.x-P.x)/100;
let my_i = (S.y-P.y)/Math.hypot(S.x-P.x, S.y-P.y) + (N_up.y-P.y)/100;
let ml_i = Math.hypot(mx_i, my_i);
ctx.fillText("i", P.x + (mx_i/ml_i)*65, P.y + (my_i/ml_i)*65);
let mx_r = (Pref.x-P.x)/Math.hypot(Pref.x-P.x, Pref.y-P.y) + (N_up.x-P.x)/100;
let my_r = (Pref.y-P.y)/Math.hypot(Pref.x-P.x, Pref.y-P.y) + (N_up.y-P.y)/100;
let ml_r = Math.hypot(mx_r, my_r);
ctx.fillText("i'", P.x + (mx_r/ml_r)*70, P.y + (my_r/ml_r)*70);
let mx_ref = (Prefrac.x-P.x)/Math.hypot(Prefrac.x-P.x, Prefrac.y-P.y) + (N_down.x-P.x)/100;
let my_ref = (Prefrac.y-P.y)/Math.hypot(Prefrac.x-P.x, Prefrac.y-P.y) + (N_down.y-P.y)/100;
let ml_ref = Math.hypot(mx_ref, my_ref);
ctx.fillText("r", P.x + (mx_ref/ml_ref)*65, P.y + (my_ref/ml_ref)*65);
