updateBounds(0, 150);
updateBounds(640, 150);
updateBounds(640, 300);
updateBounds(0, 300);
updateBounds(320, 50);
updateBounds(320, 250);
updateBounds(200, 30);
updateBounds(390, 250);
updateTextBounds("空气", 100, 100);
updateTextBounds("水", 100, 200);
if (minX === Infinity) { minX = 0; maxX = 640; minY = 0; maxY = 300; }
const contentW = maxX - minX;
const contentH = maxY - minY;
const maxSafeW = logicalWidth - padding * 2;
