const distOut = Math.hypot(pEnd.x - pC.x, pEnd.y - pC.y);
const totalDist = distIn + distOut;
const currentDist = (progress / 100) * totalDist;
const rayColor = '#FF9F43';
if (currentDist <= distIn) {
const ratio = currentDist / distIn;
const curX = pStart.x + (pC.x - pStart.x) * ratio;
const curY = pStart.y + (pC.y - pStart.y) * ratio;
drawArrow(ctx, pStart.x, pStart.y, curX, curY, rayColor);
} else {
drawArrow(ctx, pStart.x, pStart.y, pC.x, pC.y, rayColor);
const ratio = (currentDist - distIn) / distOut;
const curX = pC.x + (pEnd.x - pC.x) * ratio;
const curY = pC.y + (pEnd.y - pC.y) * ratio;
drawArrow(ctx, pC.x, pC.y, curX, curY, rayColor);
}
ctx.restore();
if (progress < 100) {
progress += 2;
rafId = requestAnimationFrame(draw);
} else {
isAnimating = false;
btn.innerText = "重播斜射偏折过程";
}
}
const btn = document.createElement('button');
btn.innerText = "播放光线斜射过程";
