if (isAnimating) return;
isAnimating = true;
progress = 0;
btn.innerText = "演示中...";
if (rafId) cancelAnimationFrame(rafId);
draw();
};
wrapper.appendChild(btn);
draw();
if (typeof cb === 'function') cb();
}

