function ai_drawCircuitInteraction(container, cb) {
const wrapper = document.createElement('div');
wrapper.style.display = 'flex';
wrapper.style.flexDirection = 'column';
wrapper.style.alignItems = 'center';
wrapper.style.width = '100%';
const cvs = document.createElement('canvas');
cvs.style.width = '100%';
cvs.style.height = 'auto';
wrapper.appendChild(cvs);
const btn = document.createElement('button');
btn.innerText = '演示电流流动';
btn.style.marginTop = '15px';
btn.style.padding = '8px 20px';
btn.style.backgroundColor = '#FF6B6B';
btn.style.color = '#FFFFFF';
btn.style.border = 'none';
btn.style.borderRadius = '20px';
btn.style.fontSize = '14px';
btn.style.fontWeight = 'bold';
btn.style.boxShadow = '0 4px 0 #D9534F';
btn.style.cursor = 'pointer';
wrapper.appendChild(btn);
container.appendChild(wrapper);
const dpr = window.devicePixelRatio || 1;
const logicalWidth = 640;
const padding = 25;
const fontSize = 28;
let minX = 90, maxX = 550, minY = 10, maxY = 290;
const contentW = maxX - minX;
const contentH = maxY - minY;
const maxSafeW = logicalWidth - padding * 2;
let safeScale = 1;
if (contentW > maxSafeW) { safeScale = maxSafeW / contentW; }
const finalHeight = (contentH * safeScale) + padding * 2;
cvs.width = logicalWidth * dpr;
cvs.height = finalHeight * dpr;
const ctx = cvs.getContext('2d');
ctx.scale(dpr, dpr);
ctx.lineCap = 'round';
ctx.lineJoin = 'round';
const offsetX = (logicalWidth - contentW * safeScale) / 2 - minX * safeScale;
const offsetY = padding - minY * safeScale;
function drawPhysical(ctx, name, sub, val, unit, x, y, color) {
let cursor = x;
ctx.textAlign = 'left';
ctx.textBaseline = 'alphabetic';
ctx.fillStyle = color;
ctx.font = `italic ${fontSize}px "Times New Roman"`;
ctx.fillText(name, cursor, y);
cursor += ctx.measureText(name).width;
if(sub) {
ctx.font = `normal ${fontSize * 0.75}px "Times New Roman"`;
ctx.fillText(sub, cursor, y + 8);
cursor += ctx.measureText(sub).width + 3;
}
if(val) {
ctx.font = `normal ${fontSize}px "Times New Roman"`;
const str = " = " + val + unit;
ctx.fillText(str, cursor, y);
}
}
function render(progress) {
ctx.save();
ctx.setTransform(1, 0, 0, 1, 0, 0);
ctx.clearRect(0, 0, cvs.width, cvs.height);
ctx.restore();
ctx.save();
ctx.translate(offsetX, offsetY);
ctx.scale(safeScale, safeScale);
ctx.beginPath();
ctx.strokeStyle = '#333333';
ctx.lineWidth = 4;
ctx.moveTo(380, 250);
ctx.lineTo(280, 250);
ctx.moveTo(280, 250);
ctx.arc(280, 250, 4, 0, Math.PI * 2);
ctx.fill();
ctx.moveTo(200, 250);
ctx.arc(200, 250, 4, 0, Math.PI * 2);
ctx.fill();
if (progress > 0) {
ctx.moveTo(280, 250);
ctx.lineTo(200, 250);
} else {
ctx.moveTo(280, 250);
ctx.lineTo(210, 230);
}
ctx.moveTo(200, 250);
ctx.lineTo(120, 250);
ctx.lineTo(120, 100);
ctx.lineTo(170, 100);
ctx.moveTo(230, 100);
ctx.lineTo(410, 100);
ctx.moveTo(470, 100);
ctx.lineTo(520, 100);
ctx.lineTo(520, 250);
ctx.lineTo(400, 250);
ctx.stroke();
ctx.beginPath();
ctx.lineWidth = 6;
ctx.moveTo(380, 220);
ctx.lineTo(380, 280);
ctx.stroke();
ctx.beginPath();
ctx.lineWidth = 8;
ctx.moveTo(400, 235);
ctx.lineTo(400, 265);
ctx.stroke();
ctx.beginPath();
ctx.lineWidth = 4;
ctx.fillStyle = '#FFFFFF';
ctx.rect(170, 85, 60, 30);
ctx.rect(410, 85, 60, 30);
ctx.fill();
ctx.stroke();
drawPhysical(ctx, 'R', '1', '40', 'Ω', 150, 70, '#333333');
drawPhysical(ctx, 'P', '1', '16', 'W', 150, 35, '#1DD1A1');
drawPhysical(ctx, 'R', '2', '120', 'Ω', 390, 70, '#333333');
drawPhysical(ctx, 'P', '2', '?', '', 390, 35, '#FF6B6B');
ctx.fillStyle = '#333333';
ctx.font = `normal ${fontSize}px "Times New Roman"`;
ctx.fillText("S", 230, 220);
ctx.fillText("+", 365, 230);
ctx.fillText("-", 410, 230);
if (progress > 0) {
const path = [
{x: 380, y: 250}, {x: 280, y: 250}, {x: 200, y: 250},
{x: 120, y: 250}, {x: 120, y: 100}, {x: 200, y: 100},
{x: 440, y: 100}, {x: 520, y: 100}, {x: 520, y: 250},
{x: 400, y: 250}
];
let totalLen = 0;
let segs = [];
for(let i=0; i<path.length-1; i++){
let dx = path[i+1].x - path[i].x;
let dy = path[i+1].y - path[i].y;
let len = Math.hypot(dx, dy);
segs.push({len, dx, dy});
totalLen += len;
}
const numDots = 8;
for(let j=0; j<numDots; j++) {
let p = (progress + j/numDots) % 1.0;
let curLen = p * totalLen;
let curP = {x: path[0].x, y: path[0].y};
for(let i=0; i<segs.length; i++){
if(curLen <= segs[i].len){
let ratio = curLen / segs[i].len;
curP.x = path[i].x + segs[i].dx * ratio;
curP.y = path[i].y + segs[i].dy * ratio;
break;
}
curLen -= segs[i].len;
}
ctx.beginPath();
ctx.fillStyle = '#FF6B6B';
ctx.arc(curP.x, curP.y, 6, 0, Math.PI*2);
ctx.fill();
ctx.lineWidth = 2;
ctx.strokeStyle = '#FFFFFF';
ctx.stroke();
}
if (progress > 0.1) {
let cx = 320;
let cy = 160;
ctx.globalAlpha = Math.min(1, progress * 2);
ctx.fillStyle = '#FF9F43';
ctx.textAlign = 'center';
ctx.font = `bold ${fontSize+2}px "Times New Roman"`;
ctx.fillText("串联电路，电流相等", cx, cy);
let cursor = cx - 55;
ctx.textAlign = 'left';
ctx.fillStyle = '#FF9F43';
ctx.font = `italic ${fontSize}px "Times New Roman"`;
ctx.fillText("I", cursor, cy + 40);
cursor += ctx.measureText("I").width;
ctx.font = `normal ${fontSize*0.75}px "Times New Roman"`;
ctx.fillText("1", cursor, cy + 45);
cursor += ctx.measureText("1").width + 5;
ctx.font = `normal ${fontSize}px "Times New Roman"`;
ctx.fillText(" = ", cursor, cy + 40);
cursor += ctx.measureText(" = ").width;
ctx.font = `italic ${fontSize}px "Times New Roman"`;
ctx.fillText("I", cursor, cy + 40);
cursor += ctx.measureText("I").width;
ctx.font = `normal ${fontSize*0.75}px "Times New Roman"`;
ctx.fillText("2", cursor, cy + 45);
ctx.globalAlpha = 1.0;
}
}
ctx.restore();
}
render(0);
let isAnimating = false;
let reqId = null;
let currentProgress = 0;
btn.onclick = () => {
if (isAnimating) return;
isAnimating = true;
currentProgress = 0.01;
btn.innerText = '演示中...';
btn.style.transform = 'translateY(2px)';
btn.style.boxShadow = '0 2px 0 #D9534F';
function animate() {
currentProgress += 0.005;
render(currentProgress);
if (currentProgress < 2.5) {
reqId = requestAnimationFrame(animate);
} else {
isAnimating = false;
render(2.5);
btn.innerText = '重播电流流动';
btn.style.transform = 'translateY(0)';
btn.style.boxShadow = '0 4px 0 #D9534F';
}
}
animate();
};
if (typeof cb === 'function') cb();
}

