ctx.moveTo(leftX, y1); ctx.lineTo(leftX, y4);
ctx.moveTo(rightX, y1); ctx.lineTo(rightX, y4);
[y1, y2, y3].forEach(y => {
ctx.moveTo(leftX, y);
ctx.lineTo(320 - RWidth/2, y);
ctx.moveTo(320 + RWidth/2, y);
ctx.lineTo(rightX, y);
ctx.stroke();
